   712→  function joinWaitlist(zip, email, name, wBtn) {
   713→    wBtn.disabled = true;
   714→    var wBtnIcon = wBtn.querySelector('.zcc-wl-btn-icon');
   715→    var wBtnLabel = wBtn.querySelector('.zcc-wl-btn-label');
   716→    if (wBtnIcon) wBtnIcon.innerHTML = ICONS.spinner;
   717→    if (wBtnLabel) wBtnLabel.textContent = 'Submitting\u2026';
   718→    if (!wBtnIcon && !wBtnLabel) wBtn.textContent = 'Submitting\u2026';
   719→
   720→    var payload = { shop: SHOP, zip: zip, email: email };
   721→    if (name) payload.name = name;
   722→
   723→    fetch(API_BASE + "/api/waitlist", {
   724→      method: "POST",
   725→      headers: { "Content-Type": "application/json" },
   726→      body: JSON.stringify(payload),
   727→    })
   728→      .then(function (r) { return r.json(); })
   729→      .then(function (data) {
   730→        var wlEl = wBtn.closest(".zcc-wl");
   731→        if (data.success) {
   732→          if (wlEl) wlEl.innerHTML =
   733→            '<div class="zcc-wl-success">' +
   734→            '<span class="zcc-wl-success-icon">' + ICONS.checkmark + '</span>' +
   735→            '<span>Your request has been submitted! We\u2019ll notify you when delivery is available.</span>' +
   736→            '</div>';
   737→        } else {
   738→          wBtn.disabled = false;
   739→          if (wBtnIcon) wBtnIcon.innerHTML = ICONS.mail;
   740→          if (wBtnLabel) wBtnLabel.textContent = 'Submit Request';
   741→          if (!wBtnIcon && !wBtnLabel) wBtn.textContent = 'Submit Request';
   742→        }
   743→      })
   744→      .catch(function () {
   745→        wBtn.disabled = false;
   746→        if (wBtnIcon) wBtnIcon.innerHTML = ICONS.mail;
   747→        if (wBtnLabel) wBtnLabel.textContent = 'Submit Request';
   748→        if (!wBtnIcon && !wBtnLabel) wBtn.textContent = 'Submit Request';
   749→      });
   750→  }
