   269→// ── Scope custom CSS for admin preview — prefix selectors with #wid ─────────
   270→function scopeAdminCss(rawCss: string | null | undefined, wid: string): string {
   271→  if (!rawCss) return "";
   272→  const css = rawCss.replace(/<\/style>/gi, "");
   273→  let result = "";
   274→  let remaining = css;
   275→  while (remaining.length > 0) {
   276→    const openBrace = remaining.indexOf("{");
   277→    if (openBrace === -1) break;
   278→    const closeBrace = remaining.indexOf("}", openBrace);
   279→    if (closeBrace === -1) break;
   280→    const selector = remaining.substring(0, openBrace).trim();
   281→    const body = remaining.substring(openBrace + 1, closeBrace);
   282→    remaining = remaining.substring(closeBrace + 1);
   283→    if (selector.startsWith("@")) {
   284→      result += selector + "{" + body + "}";
   285→    } else if (selector) {
   286→      const prefixed = selector.split(",").map(s => {
   287→        s = s.trim();
   288→        return s ? "#" + wid + " " + s : "";
   289→      }).filter(Boolean).join(", ");
   290→      result += prefixed + " {" + body + "}";
   291→    }
   292→  }
   293→  return result;
   294→}
