   329→function buildWidgetCss(wid: string, cfg: WidgetConfig): string {
   330→  const W = "#" + wid;
   331→  const p = cfg.primaryColor;
   332→  const s = cfg.successColor;
   333→  const e = cfg.errorColor;
   334→  const btnRadius = (cfg.borderRadius || "10") + "px";
   335→  const base =
   336→    "@keyframes zcc-slide-in{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}" +
   337→    "@keyframes zcc-scale-in{from{transform:scale(0.92);opacity:0}to{transform:scale(1);opacity:1}}" +
   338→    "@keyframes zcc-pulse-ring{0%{transform:scale(1);opacity:.5}50%{transform:scale(1.2);opacity:0}100%{transform:scale(1.2);opacity:0}}" +
   339→    W + "{background:transparent;color:" + cfg.textColor + ";padding:0;border:none;box-shadow:none;max-width:480px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;box-sizing:border-box}" +
   340→    W + " *{box-sizing:border-box}" +
   341→    W + " .zcc-heading{font-size:15px;font-weight:700;letter-spacing:-0.01em;margin:0;color:" + cfg.textColor + ";display:flex;align-items:center;gap:8px;padding-bottom:12px;border-bottom:1px solid rgba(0,0,0,0.06);margin-bottom:12px}" +
   342→    W + " .zcc-heading-icon{display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:50%;background:linear-gradient(135deg," + p + "18," + p + "08);flex-shrink:0}" +
   343→    W + " .zcc-heading-icon svg{width:14px;height:14px}" +
   344→    W + " .zcc-search-bar{display:flex;flex-direction:row;gap:10px;align-items:stretch}" +
   345→    W + " .zcc-input{flex:1;min-width:0;padding:12px 16px;font-size:14px;border:1.5px solid #e0e0e0;border-radius:" + btnRadius + ";outline:none;background:#fafbfb;color:" + cfg.textColor + ";transition:border-color 0.2s,box-shadow 0.2s}" +
   346→    W + " .zcc-input:focus{border-color:" + p + ";box-shadow:0 0 0 3px " + p + "15}" +
   347→    W + " .zcc-input::placeholder{color:#9ca3af}" +
   348→    W + " .zcc-btn{flex-shrink:0;white-space:nowrap;background:" + p + ";color:#fff;border:none;padding:12px 24px;font-size:14px;font-weight:600;cursor:pointer;border-radius:" + btnRadius + ";box-shadow:0 2px 8px " + p + "25;transition:filter 0.2s,box-shadow 0.2s,transform 0.2s;display:flex;align-items:center;justify-content:center;gap:6px}" +
   349→    W + " .zcc-btn:hover{filter:brightness(1.06);box-shadow:0 4px 14px " + p + "40;transform:translateY(-1px)}" +
   350→    W + " .zcc-btn:active{filter:brightness(0.95);transform:translateY(0)}" +
   351→    W + " .zcc-btn:disabled{opacity:.6;cursor:not-allowed;transform:none;box-shadow:none;filter:none}" +
   352→    W + " .zcc-btn--error{background:" + e + "10;color:" + e + ";font-weight:700;box-shadow:none}" +
   353→    W + " .zcc-result{margin-top:10px;padding:12px 14px;border-radius:12px;font-size:13.5px;line-height:1.5;animation:zcc-slide-in 0.4s cubic-bezier(0.34,1.56,0.64,1);display:flex;gap:10px;align-items:flex-start;justify-content:space-between}" +
   354→    W + " .zcc-result.ok{background:" + s + "08;border:1px solid " + s + "18}" +
   355→    W + " .zcc-result.fail{background:" + e + "08;border:1px solid " + e + "18}" +
   356→    W + " .zcc-wl{margin-top:10px;padding:14px;background:linear-gradient(135deg,#f8fafc,#f1f5f9);border-radius:12px;border:1px solid #e2e8f0}" +
   357→    W + " .zcc-wl-input{border-radius:8px;border:1.5px solid #dee2e6;padding:10px 14px;width:100%;display:block;margin-bottom:6px;outline:none;font-size:13px;transition:border-color 0.2s;background:#fff}" +
   358→    W + " .zcc-wl-btn{border-radius:50px;background:" + p + ";color:#fff;padding:10px;width:100%;font-weight:600;border:none;cursor:pointer;font-size:13px;transition:filter 0.2s,transform 0.2s}" +
   359→    W + " .zcc-wl-btn:hover{filter:brightness(1.06);transform:translateY(-1px)}" +
   360→    buildSharedMetaCss(W, cfg);
   361→  return base + scopeAdminCss(cfg.customCss, wid);
