   922→// ── Reusable position tile selector ─────────────────────────────────────────
   923→const PositionTile = memo(function PositionTile({
   924→  value,
   925→  label,
   926→  selected,
   927→  disabled,
   928→  onSelect,
   929→  children,
   930→}: {
   931→  value: string;
   932→  label: string;
   933→  selected: boolean;
   934→  disabled: boolean;
   935→  onSelect: (v: string) => void;
   936→  children: React.ReactNode;
   937→}) {
   938→  const handleClick = useCallback(() => {
   939→    if (!disabled) onSelect(value);
   940→  }, [disabled, onSelect, value]);
   941→
   942→  return (
   943→    <button
   944→      type="button"
   945→      aria-pressed={selected}
   946→      onClick={handleClick}
   947→      disabled={disabled}
   948→      onKeyDown={(e) => {
   949→        if ((e.key === "Enter" || e.key === " ") && !disabled) {
   950→          e.preventDefault();
   951→          onSelect(value);
   952→        }
   953→      }}
   954→      style={{
