   970→        boxShadow: selected
   971→          ? "0 0 0 2px var(--p-color-border-emphasis)"
   972→          : "0 0 0 1px var(--p-color-border)",
   973→        fontFamily: "inherit",
   974→        color: "inherit",
   975→        fontSize: "inherit",
   976→      }}
   977→    >
   978→      <BlockStack gap="100" inlineAlign="center">
   979→        {children}
   980→        <Text as="p" variant="bodySm" fontWeight={selected ? "semibold" : "regular"}>
